import{_ as a,o as s,c as n,a2 as d,j as o,a as e,t as l}from"./chunks/framework.CnHmQiA8.js";const m=JSON.parse('{"title":"格式预设与自制模板","description":"","frontmatter":{"title":"格式预设与自制模板","outline":[2,3]},"headers":[],"relativePath":"guide/templates.md","filePath":"guide/templates.md","lastUpdated":1795441506000}'),i={name:"guide/templates.md"};function c(r,t,g,p,_,u){return s(),n("div",null,[t[6]||(t[6]=d('<h1 id="格式预设与自制模板" tabindex="-1">格式预设与自制模板 <a class="header-anchor" href="#格式预设与自制模板" aria-label="Permalink to &quot;格式预设与自制模板&quot;">​</a></h1><p>软件通过 <strong>格式预设（<code>preset.json</code>）</strong> 和 <strong>Word 模板（<code>template.docx</code>）</strong> 控制导出的版式结构与外观，既可以直接选用内置预设，也可以复制改造成自己学校或教研组的专属样式。</p><h2 id="_1-四套内置格式预设" tabindex="-1">1. 四套内置格式预设 <a class="header-anchor" href="#_1-四套内置格式预设" aria-label="Permalink to &quot;1. 四套内置格式预设&quot;">​</a></h2><p>在“新建教学案”“从 Word 文档新建”时可以切换预设，也可以在首页 <strong>设置…</strong> 中指定“导入时默认格式预设”：</p><table tabindex="0"><thead><tr><th>预设名称</th><th>适用场景</th><th>核心特点</th></tr></thead><tbody><tr><td><strong>物理教学案 V1.0</strong></td><td>常规物理新授课 / 复习课教案学案</td><td>包含大标题、栏目标题（知识梳理 / 例题精讲 / 课堂练习 / 课后练习 / 课堂总结）、题型分组与作业单模块；页眉自动带 <code>(教案)</code> / <code>(学案)</code> 后缀；导入时自动把 <code>【详解】</code> 转为 <code>【解析】</code> 并统一解析为黑色</td></tr><tr><td><strong>物理知识点手册 V1.0</strong></td><td>知识清单、考前默写讲义</td><td>结构精简，仅包含大标题与“一、二、三……”知识点；<strong>学生版自动把标为“重点”（红色加粗下划线）的文字、公式与表格内容挖空成横线</strong>，用于课堂默写；页眉不加 <code>(教案)</code> / <code>(学案)</code></td></tr><tr><td><strong>物理题型整理 V1.0</strong></td><td>单题母题突破、题型归纳小页册</td><td>一份讲透一道母题：例题、审题（灰底注释框）、解题（<code>思维过程 / 书写过程</code> 对照表）、易错提醒、题后归纳；题目不编号，标题用黑体，默认 1.3 倍行距；学生版把对照表书写栏换为虚线格；预制模块自带整份骨架、注释框与续表</td></tr><tr><td><strong>数学教学案 V1.0</strong></td><td>数学新授课 / 例题带变式教学案</td><td>栏目为知识梳理 / 例题精讲 / 课堂练习 / 课堂总结 / 课后练习；难度分 <code>A～E</code> 五级；默认开启 <strong>审题</strong> 与 <strong>重点题</strong> 可选项；<strong>从墨案导入的教案默认使用此预设</strong></td></tr></tbody></table><h2 id="_2-自制与分享模板" tabindex="-1">2. 自制与分享模板 <a class="header-anchor" href="#_2-自制与分享模板" aria-label="Permalink to &quot;2. 自制与分享模板&quot;">​</a></h2><p>内置模板为只读状态，不能直接修改，但你可以复制一份改造成自己的版本：</p><h3 id="第一步-复制为新模板" tabindex="-1">第一步：复制为新模板 <a class="header-anchor" href="#第一步-复制为新模板" aria-label="Permalink to &quot;第一步：复制为新模板&quot;">​</a></h3><ol><li>在首页左侧栏进入 <strong>模板…</strong> 对话框。</li><li>选中最接近你需求的内置模板，点击 <strong>复制为新模板</strong>。</li><li>软件会在你的模板目录（默认为 <code>文档\\教学案\\模板\\</code>，随教学案库路径走）下创建一个新模板文件夹，包含 <code>preset.json</code>、<code>template.docx</code>、<code>header/</code> 和说明文件 <code>README.md</code>。</li></ol><h3 id="第二步-自定义修改" tabindex="-1">第二步：自定义修改 <a class="header-anchor" href="#第二步-自定义修改" aria-label="Permalink to &quot;第二步：自定义修改&quot;">​</a></h3><p>打开新建的模板文件夹，按需编辑：</p>',11)),o("ul",null,[t[5]||(t[5]=d("<li><strong>调整格式预设（<code>preset.json</code>）</strong>：可修改模板显示名称（<code>name</code>）、大标题/栏目标题/题型分组的字体与字号（<code>headings</code>）、常用栏目名称（<code>sectionNames</code>）、默认行距（<code>lineSpacing</code>）、是否开启审题/重点题（<code>questionFields</code>）、页眉文字与是否追加 <code>(教案)/(学案)</code> 后缀（<code>header</code>）、作业单字段（<code>worksheet</code>）或默写挖空规则（<code>dictation</code>）等。</li>",1)),o("li",null,[t[0]||(t[0]=o("strong",null,[e("修改页眉与纸张（"),o("code",null,"template.docx"),e(" / "),o("code",null,"header/"),e("）")],-1)),t[1]||(t[1]=e("：可在 ",-1)),t[2]||(t[2]=o("code",null,"template.docx",-1)),t[3]||(t[3]=e(" 中调整学校 Logo、页眉电话、水印与页面设置（务必保留正文占位符 ",-1)),o("code",null,l(r.body),1),t[4]||(t[4]=e(" 及原有样式名称）。",-1))])]),t[7]||(t[7]=d('<div class="warning custom-block"><p class="custom-block-title">关于修改样式字号的边界</p><p>目前只有三级标题（大标题、栏目标题、题型分组）的格式支持在 <code>preset.json</code> 中独立覆盖；正文、题目、选项等共用样式由软件内排版引擎统一绘制。因此不建议直接更改 <code>template.docx</code> 中正文和题目样式的字号缩进，以免出现预览与导出 Word 不一致。</p></div><h3 id="第三步-重新载入与导出分享" tabindex="-1">第三步：重新载入与导出分享 <a class="header-anchor" href="#第三步-重新载入与导出分享" aria-label="Permalink to &quot;第三步：重新载入与导出分享&quot;">​</a></h3><ol><li>改好后回到首页 <strong>模板…</strong> 对话框，点击 <strong>重新载入</strong>，新建教学案时就能选到你的自制模板了（如果 JSON 字段或模板占位符有误，对话框会直接列出具体中文错误原因）。</li><li>想分享给教研组其他老师？在对话框中点击 <strong>导出为 zip</strong> 发给对方，对方在自己的软件里点 <strong>导入模板…</strong> 即可一键装上。</li><li>自制模板保存在教学案库里，<strong>升级软件版本时不会被覆盖</strong>。</li></ol>',3))])}const b=a(i,[["render",c]]);export{m as __pageData,b as default};
